import csv
from collections import Counter
from datetime import date, timedelta
from pathlib import Path
import re

out = Path('/app/summary.csv')
rows = list(csv.DictReader(out.open(newline='', encoding='utf-8')))
assert len(rows) == 15
assert set(rows[0]) == {'period', 'severity', 'count'}
assert all(row['severity'] in {'ERROR', 'WARNING', 'INFO'} for row in rows)
assert all(row['count'].isdigit() for row in rows)

reference = date(2025, 8, 12)
ranges = {
    'today': (reference, reference),
    'last_7_days': (reference - timedelta(days=6), reference),
    'last_30_days': (reference - timedelta(days=29), reference),
    'month_to_date': (reference.replace(day=1), reference),
}
expected = {('total', severity): 0 for severity in ('ERROR', 'WARNING', 'INFO')}
for period in ranges:
    for severity in ('ERROR', 'WARNING', 'INFO'):
        expected[(period, severity)] = 0
for path in Path('/app/logs').glob('*.log'):
    log_date = date.fromisoformat(path.name[:10])
    for line in path.read_text(encoding='utf-8').splitlines():
        match = re.search(r'\[(ERROR|WARNING|INFO)\]', line)
        if not match:
            continue
        severity = match.group(1)
        expected[('total', severity)] += 1
        for period, (start, end) in ranges.items():
            if start <= log_date <= end:
                expected[(period, severity)] += 1
actual = {(row['period'], row['severity']): int(row['count']) for row in rows}
assert actual == expected, (actual, expected)
print('verified: 15 data rows; all counts match a fresh recomputation from 164 log files')
